#pragma once
//
// slanCM — 200 колормап, ТАБЛИЦА ДАННЫХ. Файл сгенерирован, руками не
// правится. Источник — `slanCM_Data.mat` из архива библиотеки (на машине
// автора: D:\HDD\Rybin_Matlab\slanCM\). Порядок карт = порядок поля
// `fullNames` в этом .mat, он же «родная» нумерация 1..200. Для каждой карты
// берутся её 256 опорных цветов как есть, каждый канал -> round(v * 255):
// ровно то, что делает slanCM(<idx>, 256) в MATLAB. Проверено побитово на пяти
// картах, которые до этого лежали в проекте отдельными таблицами (#151
// gist_stern, #152 gnuplot, #162 gist_rainbow, #170 nipy_spectral,
// #171 gist_ncar) — совпадение полное, поэтому старые сессии с этими картами
// рисуются пиксель-в-пиксель как раньше.
//
// Нумерация 1..200 — «родная» slanCM (индекс в fullNames), она же показана
// пользователю в пикере и в Settings. В коде id карты = kSlanCmIdBase + N,
// см. plot_renderer.h.
//
// Layout kSlanCmLut умышленно совпадает с тем, что ждёт glTexImage2D для
// 256x200 RGB8 (строка = одна карта), поэтому текстура заливается прямо из
// этого массива, без промежуточного буфера.
//
// Включается ТОЛЬКО в plot_renderer.cpp: файл большой, и таскать его в другие
// TU незачем — имена/категории/сэмплирование наружу отдаёт plot_renderer.h.
//
// -------------------------------------------------------------------------
// Источник: slanCM (200 colormaps), Zhaoxu Liu / slandarer, MATLAB File
// Exchange #120088. Сами карты собраны из matplotlib, scicomap и cmasher.
